FUNCTION_BLOCK FB_OlympicPoolOzoneORPDosing
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnableSys        : BOOL;     (* System overall enable from SCADA *)
    bEStopOK          : BOOL;     (* E-Stop OK, hardwired safety relay *)
    rFlowRate         : REAL;     (* Main circulation flow rate in m3/h *)
    rORP_Sensor1      : REAL;     (* Primary ORP reading in mV *)
    rORP_Sensor2      : REAL;     (* Secondary ORP reading in mV for redundancy *)
    rpH_Value         : REAL;     (* Pool pH value, needed for ORP compensation *)
    bOzoneGeneratorOK : BOOL;     (* Ozone generator fault status *)
    rTemp             : REAL;     (* Pool water temperature in deg C *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemRunning    : BOOL;     (* Dosing and Ozone system active *)
    rOzoneCommand     : REAL;     (* Output to Ozone Generator 0-100% *)
    rChlorineDosing   : REAL;     (* Output to Sodium Hypochlorite pump 0-100% *)
    bCriticalAlarm    : BOOL;     (* Critical alarm output (shutdown) *)
    bWarningAlarm     : BOOL;     (* Warning alarm (maintenance needed) *)
    iStateCurrent     : INT;      (* Current state machine step *)
END_VAR
VAR
    (* Internal state variables *)
    iState            : INT := 0;
    rFilteredORP      : REAL;
    rErrorORP         : REAL;
    rTargetORP        : REAL := 750.0; (* Setpoint in mV *)
    tOzoneStart       : TON;
    tSampleTimer      : TON;
    rIntegral         : REAL := 0.0;
    rDerivative       : REAL := 0.0;
    rLastORP          : REAL := 0.0;
    Kp                : REAL := 0.5;
    Ki                : REAL := 0.05;
    Kd                : REAL := 0.1;
    tSampleTime       : TIME := T#1S;
    rMaxOzone         : REAL := 100.0;
    rMinOzone         : REAL := 0.0;
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEStopOK THEN
    bSystemRunning := FALSE;
    bCriticalAlarm := TRUE;
    rOzoneCommand := 0.0;
    rChlorineDosing := 0.0;
    iStateCurrent := 999;
    RETURN;
END_IF;

(* Sensor Validation, Filtering, and Noise Rejection *)
IF ABS(rORP_Sensor1 - rORP_Sensor2) > 100.0 THEN
    bWarningAlarm := TRUE;
    rFilteredORP := rORP_Sensor1; (* Fallback to primary sensor in case of large deviation *)
ELSE
    rFilteredORP := (rORP_Sensor1 + rORP_Sensor2) / 2.0; (* Average redundant sensors for accuracy *)
    bWarningAlarm := FALSE;
END_IF;

(* Dynamic pH Compensation on ORP Target (Standard pool chemistry adjustments) *)
IF rpH_Value > 7.6 THEN
    rTargetORP := 780.0;
ELSIF rpH_Value < 7.2 THEN
    rTargetORP := 720.0;
ELSE
    rTargetORP := 750.0;
END_IF;

(* Main Control State Machine *)
CASE iState OF
    0: (* IDLE *)
        bSystemRunning := FALSE;
        rOzoneCommand := 0.0;
        rChlorineDosing := 0.0;
        (* Interlock check: must have sufficient flow to start dosing *)
        IF bEnableSys AND (rFlowRate > 50.0) THEN
            iState := 10;
        END_IF;

    10: (* OZONE GENERATOR STARTUP SEQUENCE *)
        bSystemRunning := TRUE;
        tOzoneStart(IN := TRUE, PT := T#10S);
        (* Wait for generator purge and stabilization *)
        IF bOzoneGeneratorOK AND tOzoneStart.Q THEN
            tOzoneStart(IN := FALSE);
            iState := 20;
        END_IF;
        (* Fault detection during startup *)
        IF NOT bOzoneGeneratorOK THEN
            bCriticalAlarm := TRUE;
            iState := 999;
        END_IF;

    20: (* PID CONTROL FOR OZONE AND CHLORINE DOSING *)
        tSampleTimer(IN := NOT tSampleTimer.Q, PT := tSampleTime);
        IF tSampleTimer.Q THEN
            rErrorORP := rTargetORP - rFilteredORP;

            (* PID Anti-windup logic for the integral term *)
            IF (rOzoneCommand < rMaxOzone AND rErrorORP > 0.0) OR (rOzoneCommand > rMinOzone AND rErrorORP < 0.0) THEN
                rIntegral := rIntegral + (rErrorORP * 1.0); (* 1.0 represents the 1s sample time dt *)
            END_IF;

            rDerivative := (rFilteredORP - rLastORP) / 1.0;

            (* Calculate final PID Output for Ozone production *)
            rOzoneCommand := (Kp * rErrorORP) + (Ki * rIntegral) - (Kd * rDerivative);

            (* Output saturation and clamping *)
            IF rOzoneCommand > rMaxOzone THEN
                rOzoneCommand := rMaxOzone;
            ELSIF rOzoneCommand < rMinOzone THEN
                rOzoneCommand := rMinOzone;
            END_IF;

            (* Backup Sodium Hypochlorite Dosing Strategy *)
            IF rErrorORP > 50.0 THEN
                rChlorineDosing := 50.0; (* Fast shock boost needed *)
            ELSE
                rChlorineDosing := 10.0; (* Baseline continuous trickling for residual protection *)
            END_IF;

            rLastORP := rFilteredORP;
        END_IF;

        (* Continuous flow monitoring interlock *)
        IF rFlowRate < 40.0 THEN
            bWarningAlarm := TRUE;
            iState := 0; (* Safety fallback to IDLE due to low flow *)
        END_IF;

    999: (* CRITICAL FAULT STATE *)
        bSystemRunning := FALSE;
        rOzoneCommand := 0.0;
        rChlorineDosing := 0.0;
        (* Require operator manual reset by toggling the enable signal *)
        IF NOT bEnableSys THEN
            bCriticalAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

iStateCurrent := iState;

END_FUNCTION_BLOCK
